import { useMemo, useState } from "react";
import { useAuth } from "@/_core/hooks/useAuth";
import { startLogin } from "@/const";
import { trpc } from "@/lib/trpc";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Separator } from "@/components/ui/separator";
import { toast } from "sonner";
import SettingsSurface from "@/components/SettingsSurface";
import DifferentiatorLab from "@/components/DifferentiatorLab";
import { Activity, AlertTriangle, ArrowUpRight, Database, FileSearch, Gauge, KeyRound, LayoutDashboard, LogOut, Network, Play, Plus, RefreshCw, Search, ShieldCheck, Sparkles, Terminal, X, Zap } from "lucide-react";

type Section = "overview" | "databases" | "assistant" | "queries" | "performance" | "security" | "investigations" | "evaluation" | "schema" | "audit" | "team" | "settings" | "lab";

const navItems: Array<{ id: Section; label: string; icon: typeof LayoutDashboard }> = [
  { id: "overview", label: "Command Center", icon: LayoutDashboard },
  { id: "databases", label: "Databases", icon: Database },
  { id: "assistant", label: "AI Assistant", icon: Terminal },
  { id: "queries", label: "Query History", icon: Activity },
  { id: "performance", label: "Performance", icon: Gauge },
  { id: "security", label: "Security Posture", icon: ShieldCheck },
  { id: "investigations", label: "Investigations", icon: Search },
  { id: "evaluation", label: "AI Evaluation", icon: Activity },
  { id: "schema", label: "Schema Explorer", icon: Network },
  { id: "audit", label: "Audit Ledger", icon: FileSearch },
  { id: "team", label: "Team", icon: Network },
  { id: "settings", label: "Settings", icon: KeyRound },
  { id: "lab", label: "Differentiator Lab", icon: Sparkles },
];

function statusTone(status: string) {
  if (status === "connected") return "border-cyan-300/30 bg-cyan-300/10 text-cyan-200";
  if (status === "failed" || status === "permission_denied" || status === "schema_unavailable") return "border-pink-300/30 bg-pink-300/10 text-pink-200";
  return "border-white/15 bg-white/5 text-slate-300";
}

function formatDate(date: Date | string | null | undefined) {
  if (!date) return "—";
  return new Date(date).toLocaleString([], { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" });
}

function StatCard({ label, value, detail, icon: Icon, accent = "cyan" }: { label: string; value: string | number; detail: string; icon: typeof Database; accent?: "cyan" | "pink" }) {
  return <Card className={`relative overflow-hidden border-white/10 bg-[#0c101a]/85 shadow-[0_0_32px_rgba(0,0,0,.25)] before:absolute before:inset-x-0 before:top-0 before:h-px before:bg-gradient-to-r before:from-transparent before:${accent === "pink" ? "via-pink-300" : "via-cyan-300"} before:to-transparent`}>
    <CardContent className="p-5">
      <div className="mb-7 flex items-start justify-between"><div className="text-[10px] font-bold uppercase tracking-[0.25em] text-slate-500">{label}</div><Icon className={accent === "pink" ? "h-4 w-4 text-pink-300" : "h-4 w-4 text-cyan-300"} /></div>
      <div className="font-display text-3xl font-bold tracking-tight text-white">{value}</div>
      <div className="mt-2 text-xs text-slate-500">{detail}</div>
    </CardContent>
  </Card>;
}

export default function Home() {
  const { user, loading, isAuthenticated, logout } = useAuth();
  const [section, setSection] = useState<Section>("overview");
  const [showConnect, setShowConnect] = useState(false);
  const [search, setSearch] = useState("");
  const dashboard = trpc.dashboard.summary.useQuery(undefined, { enabled: isAuthenticated });
  const connections = trpc.connections.list.useQuery(undefined, { enabled: isAuthenticated });
  const createConnection = trpc.connections.create.useMutation({ onSuccess: () => { toast.success("Database endpoint registered"); setShowConnect(false); connections.refetch(); }, onError: error => toast.error(error.message) });
  const verifyConnection = trpc.connections.verify.useMutation({ onSuccess: result => { toast.success(result.status === "connected" ? "Connection verified" : result.status.replaceAll("_", " ")); connections.refetch(); }, onError: error => toast.error(error.message) });
  const refreshSchema = trpc.connections.refreshSchema.useMutation({ onSuccess: result => toast.success(`${result.catalog.tables.length} tables cataloged`), onError: error => toast.error(error.message) });
  const [question, setQuestion] = useState("");
  const [activeConnection, setActiveConnection] = useState<number | null>(null);
  const [requestId, setRequestId] = useState<number | null>(null);
  const [proposal, setProposal] = useState<any>(null);
  const [execution, setExecution] = useState<any>(null);
  const createRequest = trpc.assistant.createRequest.useMutation({ onSuccess: result => { setRequestId(result.id); propose.mutate({ requestId: result.id }); }, onError: error => toast.error(error.message) });
  const propose = trpc.assistant.propose.useMutation({ onSuccess: result => { setProposal(result); toast.success(result.policy ? `Policy: ${result.policy.decision}` : "Clarification required"); }, onError: error => toast.error(error.message) });
  const execute = trpc.assistant.execute.useMutation({ onSuccess: result => { setExecution(result); toast.success(`${result.rowCount} rows returned in ${result.durationMs}ms`); }, onError: error => toast.error(error.message) });
  const schema = trpc.connections.schema.useQuery({ id: activeConnection ?? 0 }, { enabled: Boolean(activeConnection) && section === "schema" });

  const filteredConnections = useMemo(() => (connections.data ?? []).filter(connection => `${connection.displayName} ${connection.host} ${connection.databaseName}`.toLowerCase().includes(search.toLowerCase())), [connections.data, search]);

  if (loading) return <div className="min-h-screen bg-[#05070c] p-10 text-cyan-200">Initializing secure session…</div>;
  if (!isAuthenticated) return <Landing onLogin={startLogin} />;

  const metrics = dashboard.data?.metrics ?? { databases: 0, connected: 0, recentQueries: 0, auditEvents: 0 };
  const active = activeConnection ? connections.data?.find(connection => connection.id === activeConnection) : connections.data?.[0];

  return <div className="min-h-screen bg-[#05070c] text-slate-100">
    <div className="pointer-events-none fixed inset-0 opacity-40 [background-image:linear-gradient(rgba(82,244,255,.04)_1px,transparent_1px),linear-gradient(90deg,rgba(82,244,255,.04)_1px,transparent_1px)] [background-size:48px_48px]" />
    <div className="relative flex min-h-screen">
      <aside className="hidden w-[260px] shrink-0 border-r border-white/10 bg-[#080b13]/90 px-5 py-6 lg:flex lg:flex-col">
        <div className="mb-10 flex items-center gap-3"><div className="grid h-10 w-10 place-items-center border border-cyan-300/50 bg-cyan-300/10 text-cyan-200 shadow-[0_0_24px_rgba(82,244,255,.18)]"><Zap className="h-5 w-5" /></div><div><div className="font-display text-sm font-bold tracking-[.16em] text-white">DBOPS<span className="text-cyan-300">.AI</span></div><div className="mt-1 text-[9px] uppercase tracking-[.28em] text-slate-500">Secure control plane</div></div></div>
        <div className="mb-3 text-[10px] font-bold uppercase tracking-[.25em] text-slate-600">Workspace</div>
        <nav className="space-y-1">{navItems.map(item => { const Icon = item.icon; return <button key={item.id} onClick={() => setSection(item.id)} className={`group flex w-full items-center gap-3 px-3 py-3 text-left text-sm transition ${section === item.id ? "bg-cyan-300/10 text-cyan-200 shadow-[inset_2px_0_0_#52f4ff]" : "text-slate-400 hover:bg-white/5 hover:text-white"}`}><Icon className="h-4 w-4" />{item.label}{section === item.id && <ArrowUpRight className="ml-auto h-3.5 w-3.5" />}</button>; })}</nav>
        <div className="mt-auto border border-white/10 bg-white/[.02] p-4"><div className="mb-3 flex items-center gap-2 text-[10px] font-bold uppercase tracking-[.22em] text-slate-500"><ShieldCheck className="h-3.5 w-3.5 text-cyan-300" /> Safety posture</div><div className="font-display text-lg font-bold text-cyan-200">READ ONLY</div><div className="mt-1 text-xs leading-relaxed text-slate-500">No mutation paths are enabled in this environment.</div></div>
      </aside>
      <main className="min-w-0 flex-1">
        <header className="flex h-[76px] items-center justify-between border-b border-white/10 bg-[#080b13]/80 px-6 backdrop-blur-xl lg:px-10"><div><div className="text-[10px] font-bold uppercase tracking-[.26em] text-cyan-300">Operations / {navItems.find(item => item.id === section)?.label}</div><h1 className="mt-1 font-display text-xl font-bold tracking-tight text-white">{section === "overview" ? "Command center" : navItems.find(item => item.id === section)?.label}</h1></div><div className="flex items-center gap-3"><div className="hidden items-center gap-2 border border-cyan-300/20 bg-cyan-300/5 px-3 py-2 text-[10px] font-bold uppercase tracking-[.18em] text-cyan-200 sm:flex"><span className="h-1.5 w-1.5 animate-pulse bg-cyan-300" /> system nominal</div><div className="hidden text-right md:block"><div className="text-xs font-medium text-white">{user?.name ?? user?.email ?? "Operator"}</div><div className="text-[10px] uppercase tracking-widest text-slate-500">{user?.role ?? "user"}</div></div><Button size="icon" variant="ghost" onClick={() => logout()} className="text-slate-400 hover:bg-pink-300/10 hover:text-pink-200"><LogOut className="h-4 w-4" /></Button></div></header>
        <div className="border-b border-white/10 px-4 py-3 lg:hidden"><ScrollArea className="w-full"><div className="flex gap-2">{navItems.map(item => <Button key={item.id} size="sm" variant={section === item.id ? "default" : "ghost"} onClick={() => setSection(item.id)}>{item.label}</Button>)}</div></ScrollArea></div>
        <div className="mx-auto max-w-[1500px] p-5 lg:p-10">
          {section === "overview" && <Overview metrics={metrics} connections={connections.data ?? []} queries={dashboard.data?.queries ?? []} audit={dashboard.data?.audit ?? []} onConnect={() => setShowConnect(true)} onNavigate={setSection} />}
          {section === "databases" && <Databases connections={filteredConnections} search={search} setSearch={setSearch} onConnect={() => setShowConnect(true)} onVerify={id => verifyConnection.mutate({ id })} onRefresh={id => { setActiveConnection(id); refreshSchema.mutate({ id }); }} />}
          {section === "assistant" && <Assistant connections={connections.data ?? []} activeConnection={activeConnection} setActiveConnection={setActiveConnection} question={question} setQuestion={setQuestion} proposal={proposal} execution={execution} requestId={requestId} onAsk={() => { setExecution(null); activeConnection && question.trim() && createRequest.mutate({ connectionId: activeConnection, question }); }} onExecute={() => requestId && proposal?.sql && execute.mutate({ requestId, sql: proposal.sql })} busy={createRequest.isPending || propose.isPending || execute.isPending} />}
          {section === "queries" && <QueryHistory queries={dashboard.data?.queries ?? []} />}
          {(section === "performance" || section === "security" || section === "investigations" || section === "evaluation" || section === "team" || section === "settings") && <RoadmapSurface section={section} />}
          {section === "schema" && <SchemaExplorer connections={connections.data ?? []} active={active} setActive={setActiveConnection} schema={schema.data} onRefresh={id => refreshSchema.mutate({ id })} />}
          {section === "audit" && <AuditLedger events={dashboard.data?.audit ?? []} />}
          {section === "lab" && <DifferentiatorLab connections={connections.data ?? []} activeConnection={active} />}
        </div>
      </main>
    </div>
    {showConnect && <ConnectDialog onClose={() => setShowConnect(false)} onSubmit={input => createConnection.mutate(input)} busy={createConnection.isPending} />}
  </div>;
}

function Landing({ onLogin }: { onLogin: () => void }) { return <div className="relative grid min-h-screen place-items-center overflow-hidden bg-[#05070c] px-6 text-white"><div className="absolute inset-0 [background-image:radial-gradient(circle_at_50%_40%,rgba(255,32,150,.12),transparent_28%),linear-gradient(rgba(82,244,255,.04)_1px,transparent_1px),linear-gradient(90deg,rgba(82,244,255,.04)_1px,transparent_1px)] [background-size:auto,48px_48px,48px_48px]" /><div className="relative max-w-3xl text-center"><div className="mx-auto mb-8 grid h-20 w-20 place-items-center border border-cyan-300/50 bg-cyan-300/10 text-cyan-200 shadow-[0_0_48px_rgba(82,244,255,.25)]"><Zap className="h-9 w-9" /></div><div className="mb-4 text-xs font-bold uppercase tracking-[.45em] text-cyan-300">Secure database operations</div><h1 className="font-display text-5xl font-black tracking-[-.05em] text-white sm:text-7xl">Query with <span className="text-pink-300 text-glow-pink">confidence.</span></h1><p className="mx-auto mt-7 max-w-2xl text-base leading-8 text-slate-400">A read-only-first PostgreSQL operations assistant. Explore schemas, ask questions in plain language, validate every proposal, and keep every action accountable.</p><Button onClick={onLogin} className="mt-9 h-12 rounded-none bg-cyan-300 px-8 font-bold uppercase tracking-[.18em] text-[#05070c] hover:bg-cyan-200">Enter control plane <ArrowUpRight className="ml-2 h-4 w-4" /></Button></div></div>; }

function Overview({ metrics, connections, queries, audit, onConnect, onNavigate }: { metrics: any; connections: any[]; queries: any[]; audit: any[]; onConnect: () => void; onNavigate: (section: Section) => void }) { return <div className="space-y-8"><div className="flex flex-col justify-between gap-4 md:flex-row md:items-end"><div><div className="mb-2 flex items-center gap-2 text-xs uppercase tracking-[.22em] text-pink-300"><span className="h-px w-8 bg-pink-300" /> live telemetry</div><h2 className="font-display text-3xl font-bold tracking-tight text-white">System overview</h2><p className="mt-2 max-w-xl text-sm leading-6 text-slate-500">Monitor your database surfaces, query activity, and operational evidence from one controlled workspace.</p></div><Button onClick={onConnect} className="rounded-none bg-pink-300 font-bold text-[#140711] hover:bg-pink-200"><Plus className="mr-2 h-4 w-4" /> Add database</Button></div><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-6"><StatCard label="Database endpoints" value={metrics.databases} detail={`${metrics.connected} verified online`} icon={Database} /><StatCard label="Read-only posture" value="100%" detail="Mutation routes disabled" icon={ShieldCheck} accent="pink" /><StatCard label="Recent query runs" value={metrics.recentQueries} detail="Last 20 requests indexed" icon={Gauge} /><StatCard label="Slow queries" value={metrics.slowQueries ?? 0} detail="Telemetry candidates" icon={AlertTriangle} accent="pink" /><StatCard label="Schema tables" value={metrics.schemaTables ?? 0} detail={`${metrics.schemaColumns ?? 0} columns cataloged`} icon={Network} /><StatCard label="Audit events" value={metrics.auditEvents} detail="Append-only lifecycle" icon={FileSearch} accent="pink" /></div><div className="grid gap-5 xl:grid-cols-[1.3fr_.7fr]"><Card className="border-white/10 bg-[#0c101a]/85"><CardHeader className="flex-row items-center justify-between"><div><CardTitle className="font-display text-base uppercase tracking-[.14em] text-white">Database surfaces</CardTitle><div className="mt-1 text-xs text-slate-500">Connection state across your workspace</div></div><Button variant="ghost" size="sm" onClick={() => onNavigate("databases")} className="text-cyan-200">View all <ArrowUpRight className="ml-1 h-3.5 w-3.5" /></Button></CardHeader><CardContent className="space-y-3">{connections.length ? connections.slice(0, 4).map(connection => <div key={connection.id} className="flex items-center justify-between border border-white/8 bg-white/[.02] p-4"><div className="flex items-center gap-3"><div className="grid h-9 w-9 place-items-center border border-cyan-300/20 bg-cyan-300/5"><Database className="h-4 w-4 text-cyan-300" /></div><div><div className="text-sm font-semibold text-white">{connection.displayName}</div><div className="mt-1 text-xs text-slate-500">{connection.host}:{connection.port} / {connection.databaseName}</div></div></div><Badge className={statusTone(connection.status)}>{connection.status.replaceAll("_", " ")}</Badge></div>) : <Empty text="No PostgreSQL endpoints connected yet." action="Connect a database" onClick={onConnect} />}</CardContent></Card><Card className="border-white/10 bg-[#0c101a]/85"><CardHeader><CardTitle className="font-display text-base uppercase tracking-[.14em] text-white">Recent activity</CardTitle></CardHeader><CardContent className="space-y-4">{audit.length ? audit.slice(0, 5).map(event => <div key={event.id} className="flex gap-3"><div className="mt-1 h-2 w-2 shrink-0 bg-pink-300 shadow-[0_0_10px_rgba(255,77,169,.8)]" /><div><div className="text-xs font-semibold text-slate-200">{event.eventType.replaceAll("_", " ")}</div><div className="mt-1 text-[11px] text-slate-500">{formatDate(event.createdAt)} · {event.status}</div></div></div>) : <div className="py-8 text-center text-sm text-slate-500">Your audit stream will appear here.</div>}</CardContent></Card></div><div className="grid gap-5 xl:grid-cols-2"><Card className="border-white/10 bg-[#0c101a]/85"><CardHeader className="flex-row items-center justify-between"><CardTitle className="font-display text-base uppercase tracking-[.14em] text-white">Query pulse</CardTitle><Activity className="h-4 w-4 text-cyan-300" /></CardHeader><CardContent>{queries.length ? <div className="space-y-3">{queries.slice(0, 4).map(query => <div key={query.id} className="border-l border-cyan-300/50 pl-3"><div className="line-clamp-1 text-sm text-slate-200">{query.naturalLanguageRequest}</div><div className="mt-1 text-[11px] uppercase tracking-wider text-slate-500">{query.status} · {formatDate(query.createdAt)}</div></div>)}</div> : <Empty text="No queries have been run." action="Open AI Assistant" onClick={() => onNavigate("assistant")} />}</CardContent></Card><Card className="border-white/10 bg-[#0c101a]/85"><CardHeader><CardTitle className="font-display text-base uppercase tracking-[.14em] text-white">Operational contract</CardTitle></CardHeader><CardContent><div className="grid gap-3 sm:grid-cols-3">{[["01", "Propose", "AI interprets intent"], ["02", "Verify", "Policy engine validates"], ["03", "Audit", "Evidence stays traceable"]].map(item => <div key={item[0]} className="border border-white/8 p-4"><div className="font-display text-xs text-pink-300">{item[0]}</div><div className="mt-3 text-sm font-semibold text-white">{item[1]}</div><div className="mt-1 text-xs leading-5 text-slate-500">{item[2]}</div></div>)}</div></CardContent></Card></div></div>; }

function Empty({ text, action, onClick }: { text: string; action: string; onClick: () => void }) { return <div className="py-12 text-center"><div className="mx-auto mb-3 grid h-10 w-10 place-items-center border border-white/10 text-slate-500"><Database className="h-4 w-4" /></div><p className="text-sm text-slate-500">{text}</p><Button variant="link" onClick={onClick} className="mt-2 text-cyan-200">{action}</Button></div>; }

function Databases({ connections, search, setSearch, onConnect, onVerify, onRefresh }: { connections: any[]; search: string; setSearch: (value: string) => void; onConnect: () => void; onVerify: (id: number) => void; onRefresh: (id: number) => void }) { return <div className="space-y-6"><div className="flex flex-col justify-between gap-4 md:flex-row md:items-end"><div><div className="mb-2 text-xs uppercase tracking-[.22em] text-cyan-300">Connection registry</div><h2 className="font-display text-3xl font-bold text-white">Database endpoints</h2></div><Button onClick={onConnect} className="rounded-none bg-pink-300 font-bold text-[#140711] hover:bg-pink-200"><Plus className="mr-2 h-4 w-4" /> Register endpoint</Button></div><div className="relative max-w-md"><Search className="absolute left-3 top-3 h-4 w-4 text-slate-500" /><Input value={search} onChange={event => setSearch(event.target.value)} placeholder="Search endpoints…" className="border-white/10 bg-white/[.04] pl-10 text-white placeholder:text-slate-600" /></div><div className="grid gap-4">{connections.map(connection => <Card key={connection.id} className="border-white/10 bg-[#0c101a]/85"><CardContent className="flex flex-col gap-5 p-5 lg:flex-row lg:items-center lg:justify-between"><div className="flex items-center gap-4"><div className="grid h-12 w-12 place-items-center border border-cyan-300/20 bg-cyan-300/5"><Database className="h-5 w-5 text-cyan-300" /></div><div><div className="font-display text-lg font-bold text-white">{connection.displayName}</div><div className="mt-1 text-xs text-slate-500">{connection.username}@{connection.host}:{connection.port} / {connection.databaseName}</div><div className="mt-3 flex flex-wrap gap-2"><Badge className={statusTone(connection.status)}>{connection.status.replaceAll("_", " ")}</Badge><Badge className="border-white/10 bg-white/5 text-slate-400">SSL {connection.sslMode}</Badge></div></div></div><div className="flex flex-wrap gap-2"><Button size="sm" variant="outline" onClick={() => onVerify(connection.id)} className="border-white/10 bg-transparent text-slate-200"><RefreshCw className="mr-2 h-3.5 w-3.5" /> Verify</Button><Button size="sm" variant="outline" onClick={() => onRefresh(connection.id)} className="border-cyan-300/20 bg-cyan-300/5 text-cyan-200"><Network className="mr-2 h-3.5 w-3.5" /> Catalog schema</Button></div></CardContent></Card>)}{!connections.length && <Empty text="No endpoints match this search." action="Register a database" onClick={onConnect} />}</div></div>; }

function Assistant({ connections, activeConnection, setActiveConnection, question, setQuestion, proposal, execution, requestId, onAsk, onExecute, busy }: { connections: any[]; activeConnection: number | null; setActiveConnection: (value: number) => void; question: string; setQuestion: (value: string) => void; proposal: any; execution: any; requestId: number | null; onAsk: () => void; onExecute: () => void; busy: boolean }) { return <div className="grid gap-6 xl:grid-cols-[.85fr_1.15fr]"><div className="space-y-5"><div><div className="mb-2 text-xs uppercase tracking-[.22em] text-pink-300">Evidence-grounded interface</div><h2 className="font-display text-3xl font-bold text-white">Ask the database.</h2><p className="mt-2 max-w-lg text-sm leading-6 text-slate-500">Every proposal is validated against the selected schema before it can execute. No blind SQL. No mutation paths.</p></div><Card className="border-white/10 bg-[#0c101a]/85"><CardHeader><CardTitle className="font-display text-sm uppercase tracking-[.14em] text-white">Request console</CardTitle></CardHeader><CardContent className="space-y-4"><label className="text-xs font-bold uppercase tracking-widest text-slate-500">Target endpoint</label><select value={activeConnection ?? ""} onChange={event => setActiveConnection(Number(event.target.value))} className="h-10 w-full border border-white/10 bg-[#080b13] px-3 text-sm text-white outline-none focus:border-cyan-300/60"><option value="">Select a connected database</option>{connections.map(connection => <option key={connection.id} value={connection.id}>{connection.displayName} · {connection.status}</option>)}</select><label className="block text-xs font-bold uppercase tracking-widest text-slate-500">Natural-language request</label><Textarea value={question} onChange={event => setQuestion(event.target.value)} placeholder="Why is the orders table slow?" className="min-h-36 resize-none border-white/10 bg-white/[.03] text-white placeholder:text-slate-600" /><div className="flex items-center justify-between border-t border-white/10 pt-4"><div className="flex items-center gap-2 text-[10px] uppercase tracking-widest text-cyan-200"><ShieldCheck className="h-3.5 w-3.5" /> read-only policy active</div><Button onClick={onAsk} disabled={busy || !activeConnection || question.trim().length < 3} className="rounded-none bg-cyan-300 font-bold text-[#05070c] hover:bg-cyan-200"><Play className="mr-2 h-4 w-4" /> {busy ? "Processing…" : "Generate proposal"}</Button></div></CardContent></Card></div><Card className="min-h-[520px] border-white/10 bg-[#0c101a]/85"><CardHeader className="flex-row items-center justify-between"><div><CardTitle className="font-display text-sm uppercase tracking-[.14em] text-white">Proposal workspace</CardTitle><div className="mt-1 text-xs text-slate-500">{requestId ? `Request #${requestId}` : "Awaiting an operator request"}</div></div>{proposal?.policy && <Badge className={proposal.policy.decision === "allow" ? "border-cyan-300/30 bg-cyan-300/10 text-cyan-200" : "border-pink-300/30 bg-pink-300/10 text-pink-200"}>{proposal.policy.decision}</Badge>}</CardHeader><CardContent>{proposal ? <div className="space-y-5"><div className="border border-cyan-300/20 bg-[#07151a] p-4"><div className="mb-3 flex items-center justify-between text-[10px] font-bold uppercase tracking-widest text-cyan-300"><span>Generated SQL</span><span>confidence {Math.round((proposal.confidence ?? 0) * 100)}%</span></div><pre className="overflow-x-auto whitespace-pre-wrap font-mono text-sm leading-6 text-cyan-50">{proposal.sql}</pre></div><div className="grid gap-3 sm:grid-cols-2"><div className="border border-white/8 p-4"><div className="text-[10px] font-bold uppercase tracking-widest text-slate-500">Assumptions</div><div className="mt-3 space-y-2 text-xs leading-5 text-slate-300">{proposal.assumptions?.map((item: string) => <div key={item}>· {item}</div>)}</div></div><div className="border border-white/8 p-4"><div className="text-[10px] font-bold uppercase tracking-widest text-slate-500">Policy evidence</div><div className="mt-3 space-y-2 text-xs leading-5 text-slate-300">{proposal.policy?.reasons?.map((item: string) => <div key={item} className="flex gap-2"><ShieldCheck className="mt-0.5 h-3.5 w-3.5 shrink-0 text-cyan-300" />{item}</div>)}</div></div></div>{proposal.policy?.decision === "allow" && !execution && <Button onClick={onExecute} disabled={busy} className="w-full rounded-none bg-pink-300 font-bold text-[#140711] hover:bg-pink-200"><Play className="mr-2 h-4 w-4" /> Execute constrained read-only query</Button>}{execution && <div className="space-y-4 border border-cyan-300/20 bg-cyan-300/[.04] p-4"><div className="flex items-center justify-between"><div className="text-[10px] font-bold uppercase tracking-widest text-cyan-300">Verified execution result</div><Badge className="border-cyan-300/30 bg-cyan-300/10 text-cyan-200">{execution.durationMs}ms</Badge></div><div className="grid grid-cols-3 gap-3 text-center"><div><div className="font-display text-lg font-bold text-white">{execution.rowCount}</div><div className="text-[10px] uppercase tracking-widest text-slate-500">rows</div></div><div><div className="font-display text-lg font-bold text-white">{execution.rows?.length ?? 0}</div><div className="text-[10px] uppercase tracking-widest text-slate-500">shown</div></div><div><div className="font-display text-lg font-bold text-white">{execution.truncated ? "capped" : "complete"}</div><div className="text-[10px] uppercase tracking-widest text-slate-500">result</div></div></div><div className="border-l-2 border-pink-300/60 bg-pink-300/[.04] p-4"><div className="mb-2 text-[10px] font-bold uppercase tracking-widest text-pink-200">Evidence-grounded explanation</div><p className="text-sm leading-6 text-slate-200">{execution.explanation}</p><div className="mt-3 text-[10px] uppercase tracking-widest text-slate-500">Generated only from returned rows, row count, duration, and limit status.</div></div><pre className="max-h-56 overflow-auto whitespace-pre-wrap font-mono text-xs leading-5 text-slate-300">{JSON.stringify(execution.rows, null, 2)}</pre></div>}</div> : <div className="grid min-h-[400px] place-items-center text-center"><div><div className="mx-auto mb-4 grid h-14 w-14 place-items-center border border-pink-300/30 bg-pink-300/5 text-pink-300"><Terminal className="h-6 w-6" /></div><div className="font-display text-lg font-bold text-white">No proposal in the workspace</div><p className="mx-auto mt-2 max-w-sm text-sm leading-6 text-slate-500">Select an endpoint and ask a question. The generated SQL, assumptions, confidence, and policy evidence will appear here.</p></div></div>}</CardContent></Card></div>; }

function QueryHistory({ queries }: { queries: any[] }) { return <div className="space-y-6"><div><div className="mb-2 text-xs uppercase tracking-[.22em] text-cyan-300">Request ledger</div><h2 className="font-display text-3xl font-bold text-white">Query history</h2></div><Card className="border-white/10 bg-[#0c101a]/85"><CardContent className="p-0">{queries.length ? queries.map((query, index) => <div key={query.id} className={`flex items-center justify-between gap-4 p-5 ${index ? "border-t border-white/8" : ""}`}><div className="min-w-0"><div className="truncate text-sm font-medium text-white">{query.naturalLanguageRequest}</div><div className="mt-2 text-[11px] uppercase tracking-widest text-slate-500">request #{query.id} · {formatDate(query.createdAt)}</div></div><Badge className={statusTone(query.status)}>{query.status}</Badge></div>) : <Empty text="No query requests yet." action="Open the AI Assistant" onClick={() => undefined} />}</CardContent></Card></div>; }

function SchemaExplorer({ connections, active, setActive, schema, onRefresh }: { connections: any[]; active: any; setActive: (value: number) => void; schema: any; onRefresh: (id: number) => void }) { const [filter, setFilter] = useState(""); const tables = schema?.tables?.filter((table: any) => `${table.schema}.${table.name} ${table.columns.map((column: any) => column.name).join(" ")}`.toLowerCase().includes(filter.toLowerCase())) ?? []; return <div className="space-y-6"><div className="flex flex-col justify-between gap-4 md:flex-row md:items-end"><div><div className="mb-2 text-xs uppercase tracking-[.22em] text-cyan-300">Metadata graph</div><h2 className="font-display text-3xl font-bold text-white">Schema explorer</h2></div><Button variant="outline" onClick={() => active && onRefresh(active.id)} className="border-cyan-300/20 bg-cyan-300/5 text-cyan-200"><RefreshCw className="mr-2 h-4 w-4" /> Refresh catalog</Button></div><div className="flex flex-col gap-3 md:flex-row"><select value={active?.id ?? ""} onChange={event => setActive(Number(event.target.value))} className="h-10 border border-white/10 bg-[#080b13] px-3 text-sm text-white outline-none"><option value="">Select endpoint</option>{connections.map(connection => <option key={connection.id} value={connection.id}>{connection.displayName}</option>)}</select><div className="relative max-w-md flex-1"><Search className="absolute left-3 top-3 h-4 w-4 text-slate-500" /><Input value={filter} onChange={event => setFilter(event.target.value)} placeholder="Filter tables and columns…" className="border-white/10 bg-white/[.04] pl-10 text-white placeholder:text-slate-600" /></div></div>{schema ? <div className="space-y-6"><div className="grid gap-3 sm:grid-cols-4"><div className="border border-white/8 bg-white/[.02] p-4"><div className="text-[10px] uppercase tracking-widest text-slate-500">tables</div><div className="mt-2 font-display text-2xl font-bold text-white">{schema.tables.length}</div></div><div className="border border-white/8 bg-white/[.02] p-4"><div className="text-[10px] uppercase tracking-widest text-slate-500">relationships</div><div className="mt-2 font-display text-2xl font-bold text-white">{schema.relationships?.length ?? 0}</div></div><div className="border border-white/8 bg-white/[.02] p-4"><div className="text-[10px] uppercase tracking-widest text-slate-500">indexes</div><div className="mt-2 font-display text-2xl font-bold text-white">{schema.indexes?.length ?? 0}</div></div><div className="border border-white/8 bg-white/[.02] p-4"><div className="text-[10px] uppercase tracking-widest text-slate-500">views</div><div className="mt-2 font-display text-2xl font-bold text-white">{schema.views?.length ?? 0}</div></div></div><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{tables.map((table: any) => <Card key={`${table.schema}.${table.name}`} className="border-white/10 bg-[#0c101a]/85"><CardHeader className="pb-3"><div className="flex items-start justify-between"><CardTitle className="font-display text-sm text-white">{table.name}</CardTitle><Badge className="border-white/10 bg-white/5 text-[10px] text-slate-500">{table.schema}</Badge></div></CardHeader><CardContent className="space-y-2">{table.columns.map((column: any) => <div key={column.name} className="flex items-center justify-between border-t border-white/5 pt-2 text-xs"><span className="text-slate-300">{column.name}</span><span className="font-mono text-[10px] text-cyan-300/70">{column.dataType}</span></div>)}</CardContent></Card>)}{!tables.length && <div className="col-span-full py-14 text-center text-sm text-slate-500">No tables match this filter.</div>}</div><div className="grid gap-4 xl:grid-cols-3"><Card className="border-white/10 bg-[#0c101a]/85"><CardHeader><CardTitle className="font-display text-xs uppercase tracking-[.14em] text-white">Relationships</CardTitle></CardHeader><CardContent className="space-y-2">{(schema.relationships ?? []).length ? schema.relationships.slice(0, 8).map((item: any, index: number) => <div key={`${item.fromTable}-${item.fromColumn}-${index}`} className="border-t border-white/8 pt-2 text-xs text-slate-300"><span className="text-cyan-200">{item.fromTable}.{item.fromColumn}</span><span className="mx-2 text-slate-600">→</span><span>{item.toTable}.{item.toColumn}</span></div>) : <div className="text-xs text-slate-500">No foreign-key relationships found.</div>}</CardContent></Card><Card className="border-white/10 bg-[#0c101a]/85"><CardHeader><CardTitle className="font-display text-xs uppercase tracking-[.14em] text-white">Indexes</CardTitle></CardHeader><CardContent className="space-y-2">{(schema.indexes ?? []).length ? schema.indexes.slice(0, 8).map((item: any) => <div key={`${item.schema}.${item.name}`} className="border-t border-white/8 pt-2"><div className="text-xs text-white">{item.name}</div><div className="mt-1 line-clamp-2 font-mono text-[10px] text-slate-500">{item.definition}</div></div>) : <div className="text-xs text-slate-500">No indexes found.</div>}</CardContent></Card><Card className="border-white/10 bg-[#0c101a]/85"><CardHeader><CardTitle className="font-display text-xs uppercase tracking-[.14em] text-white">Views and constraints</CardTitle></CardHeader><CardContent className="space-y-2">{(schema.views ?? []).map((item: any) => <div key={`${item.schema}.${item.name}`} className="border-t border-white/8 pt-2 text-xs text-cyan-200">view · {item.schema}.{item.name}</div>)}{(schema.constraints ?? []).slice(0, 8).map((item: any) => <div key={`${item.schema}.${item.table}.${item.name}`} className="border-t border-white/8 pt-2 text-xs text-slate-300">{item.type.toLowerCase()} · {item.table} ({item.columns.join(", ")})</div>)}{!(schema.views ?? []).length && !(schema.constraints ?? []).length && <div className="text-xs text-slate-500">No views or constraints found.</div>}</CardContent></Card></div></div> : <div className="border border-dashed border-white/10 py-20 text-center text-sm text-slate-500">Select a database and refresh its catalog to inspect the schema.</div>}</div>; }

function RoadmapSurface({ section }: { section: "performance" | "security" | "investigations" | "evaluation" | "team" | "settings" }) {
  const performance = trpc.performance.summary.useQuery(undefined, { enabled: section === "performance" });
  const team = trpc.team.members.useQuery(undefined, { enabled: section === "team" });
  const changeRole = trpc.team.changeRole.useMutation({ onSuccess: () => { team.refetch(); toast.success("Member role updated"); }, onError: error => toast.error(error.message) });
  const removeMember = trpc.team.remove.useMutation({ onSuccess: () => { team.refetch(); toast.success("Member removed"); }, onError: error => toast.error(error.message) });
  const evaluation = trpc.evaluation.benchmark.useQuery(undefined, { enabled: section === "evaluation" });
  const investigations = trpc.investigations.list.useQuery(undefined, { enabled: section === "investigations" });
  const security = trpc.security.posture.useQuery(undefined, { enabled: section === "security" });
  const securityScan = trpc.security.scan.useMutation({ onError: error => toast.error(error.message) });
  const dashboardSurface = trpc.dashboard.summary.useQuery(undefined, { enabled: section === "security" || section === "investigations" });
  const title = section === "performance" ? "Performance telemetry" : section === "security" ? "Security posture" : section === "investigations" ? "Investigation workspace" : section === "evaluation" ? "AI evaluation lab" : section === "team" ? "Workspace team" : "Workspace settings";
  const icon = section === "performance" ? <Gauge className="h-5 w-5" /> : section === "security" ? <ShieldCheck className="h-5 w-5" /> : section === "evaluation" ? <Activity className="h-5 w-5" /> : section === "team" ? <Network className="h-5 w-5" /> : <KeyRound className="h-5 w-5" />;
  const activeQuery = section === "performance" ? performance : section === "team" ? team : section === "evaluation" ? evaluation : section === "security" ? security : section === "investigations" ? investigations : dashboardSurface;
  if (activeQuery.isLoading) return <SurfaceFrame title={title} eyebrow="Loading telemetry" icon={icon}><EmptySurface text="Collecting workspace evidence…" /></SurfaceFrame>;
  if (activeQuery.error) return <SurfaceFrame title={title} eyebrow="Telemetry error" icon={icon}><EmptySurface text={activeQuery.error.message} /></SurfaceFrame>;
  if (section === "performance") return <SurfaceFrame title={title} eyebrow="Plan evidence" icon={icon}><div className="grid gap-4 md:grid-cols-3"><MetricPanel label="Slow query candidates" value={performance.data?.slowQueries.length ?? 0} detail="Observed executions above the current evidence threshold." /><MetricPanel label="Plans analyzed" value={performance.data?.plans.length ?? 0} detail={`Parser ${performance.data?.parser ?? "json-plan-v1"}.`} /><MetricPanel label="Recommendations" value={performance.data?.recommendations.length ?? 0} detail="Only reproducible, evidence-backed findings are shown." /></div>{performance.data?.recommendations.length ? <Card className="border-white/10 bg-[#0c101a]/85"><CardHeader><CardTitle className="font-display text-sm uppercase tracking-[.14em] text-white">Evidence-backed findings</CardTitle></CardHeader><CardContent className="space-y-3">{performance.data.recommendations.map((item, index) => <div key={`${item.requestId}-${index}`} className="border-l border-pink-300/60 bg-pink-300/[.03] p-4"><div className="text-sm font-semibold text-white">{item.message}</div><div className="mt-2 font-mono text-xs text-cyan-200">{item.evidence}</div><div className="mt-2 text-[10px] uppercase tracking-widest text-slate-500">request #{item.requestId} · observed evidence</div></div>)}</CardContent></Card> : <EmptySurface text="Connect a PostgreSQL endpoint and execute read-only queries to populate EXPLAIN evidence and transparent performance findings." />}</SurfaceFrame>;
  if (section === "team") return <SurfaceFrame title={title} eyebrow="Workspace boundary" icon={icon}><div className="flex justify-end"><Button onClick={() => toast.info("Invite delivery will be enabled when the workspace notification provider is configured")} className="rounded-none bg-pink-300 font-bold text-[#05070c] hover:bg-pink-200">Invite operator</Button></div>{team.data?.length ? <div className="grid gap-3 md:grid-cols-2">{team.data.map(member => <Card key={member.id} className="border-white/10 bg-white/[.02]"><CardContent className="space-y-4 p-5"><div className="flex items-center justify-between"><div><div className="font-semibold text-white">{member.name ?? "Unnamed operator"}</div><div className="mt-1 text-xs text-slate-500">{member.email ?? "No email on record"}</div></div><Badge className="border-cyan-300/20 bg-cyan-300/10 text-cyan-200">{member.role}</Badge></div>{member.role !== "owner" && <div className="flex gap-2"><Button size="sm" variant="outline" onClick={() => changeRole.mutate({ memberId: member.id, role: member.role === "admin" ? "viewer" : "admin" })} className="border-white/10 bg-transparent text-slate-300">Toggle role</Button><Button size="sm" variant="outline" onClick={() => removeMember.mutate({ memberId: member.id })} className="border-pink-300/20 bg-pink-300/5 text-pink-200">Remove</Button></div>}</CardContent></Card>)}</div> : <EmptySurface text="Workspace membership is isolated by authenticated user. Invite flows will populate this roster when enabled." />}</SurfaceFrame>;
  if (section === "evaluation") return <SurfaceFrame title={title} eyebrow="Quality gates" icon={icon}><div className="grid gap-4 md:grid-cols-5">{[["Accuracy", evaluation.data?.metrics.accuracy], ["Safety violations", evaluation.data?.metrics.safetyViolations], ["Hallucination rate", evaluation.data?.metrics.hallucinationRate], ["Latency", evaluation.data?.metrics.latencyMs], ["Cost", evaluation.data?.metrics.cost]].map(([label, value]) => <MetricPanel key={String(label)} label={String(label)} value={value == null ? "—" : String(value)} detail={evaluation.data?.status === "evidence_available" ? "Observed from workspace query evidence." : "Requires labeled fixture cases."} />)}</div><Card className="border-white/10 bg-[#0c101a]/85"><CardHeader><CardTitle className="font-display text-sm uppercase tracking-[.14em] text-white">Benchmark case registry</CardTitle></CardHeader><CardContent className="grid gap-3 md:grid-cols-2">{["Known-table retrieval", "Ambiguous question refusal", "Hallucinated-column rejection", "Read-only mutation block"].map(item => <div key={item} className="flex items-center justify-between border border-white/8 p-4"><span className="text-sm text-slate-300">{item}</span><Badge className="border-pink-300/20 bg-pink-300/5 text-pink-200">pending labels</Badge></div>)}</CardContent></Card><Card className="border-white/10 bg-[#0c101a]/85"><CardHeader><CardTitle className="font-display text-sm uppercase tracking-[.14em] text-white">Model evaluation context</CardTitle></CardHeader><CardContent className="grid gap-4 md:grid-cols-3"><div><label className="mb-2 block text-[10px] uppercase tracking-widest text-slate-500">Provider</label><select className="h-10 w-full border border-white/10 bg-[#080b13] px-3 text-sm text-white" defaultValue="placeholder"><option value="placeholder">Credential pending</option><option value="manus">Manus gateway</option></select></div><div><label className="mb-2 block text-[10px] uppercase tracking-widest text-slate-500">Model</label><Input value="structured-sql-proposer-v1" readOnly className="border-white/10 bg-white/[.03] text-slate-400" /></div><div className="flex items-end"><Badge className="border-pink-300/20 bg-pink-300/5 px-3 py-2 text-pink-200">API key required later</Badge></div></CardContent></Card><EmptySurface text="Workspace evidence is shown when query traces exist. Accuracy, hallucination rate, and cost remain unset until labeled fixture cases and model telemetry are supplied." /></SurfaceFrame>;
  if (section === "settings") return <SettingsSurface title={title} icon={icon} />;
  const status = section === "security" ? security.data?.status : investigations.data?.status;
  if (section === "security") return <SurfaceFrame title={title} eyebrow="Deterministic checks" icon={icon}><Card className="border-white/10 bg-white/[.02]"><CardContent className="flex flex-col gap-4 p-5 md:flex-row md:items-center md:justify-between"><div><div className="flex items-center gap-3"><Badge className="border-cyan-300/20 bg-cyan-300/10 text-cyan-200">{securityScan.data?.status ?? status}</Badge><span className="text-sm text-slate-400">Observed connection posture and catalog-based candidates only.</span></div></div><div className="flex gap-2"><select className="h-10 border border-white/10 bg-[#080b13] px-3 text-sm text-white" defaultValue=""><option value="">Select endpoint</option>{(dashboardSurface.data?.connections ?? []).map(connection => <option key={connection.id} value={connection.id}>{connection.displayName}</option>)}</select><Button onClick={event => { const select = event.currentTarget.previousElementSibling as HTMLSelectElement | null; if (select?.value) securityScan.mutate({ connectionId: Number(select.value) }); }} className="rounded-none bg-cyan-300 font-bold text-[#05070c] hover:bg-cyan-200">Run scan</Button></div></CardContent></Card><div className="grid gap-4 md:grid-cols-3">{(dashboardSurface.data?.connections ?? []).map(connection => <Card key={connection.id} className="border-white/10 bg-[#0c101a]/85"><CardContent className="p-5"><div className="text-sm font-semibold text-white">{connection.displayName}</div><div className="mt-2 text-xs text-slate-500">SSL mode: {connection.sslMode}</div><Badge className={`${statusTone(connection.status)} mt-4`}>{connection.status.replaceAll("_", " ")}</Badge></CardContent></Card>)}</div>{securityScan.data?.checks?.length ? <Card className="border-white/10 bg-[#0c101a]/85"><CardHeader><CardTitle className="font-display text-sm uppercase tracking-[.14em] text-white">Scan evidence</CardTitle></CardHeader><CardContent className="space-y-3">{securityScan.data.checks.map((check, index) => <div key={`${check.type}-${index}`} className="flex items-center justify-between border-t border-white/8 pt-3"><div><div className="text-sm text-white">{check.type.replaceAll("_", " ")}</div><div className="mt-1 text-xs text-slate-500">{check.evidence}</div></div><Badge className={check.severity === "pass" ? "border-cyan-300/20 bg-cyan-300/10 text-cyan-200" : "border-pink-300/20 bg-pink-300/5 text-pink-200"}>{check.severity}</Badge></div>)}</CardContent></Card> : <EmptySurface text="Run a scan after connecting and cataloging an endpoint to collect permission and potential-sensitive-column evidence." />}</SurfaceFrame>;
  return <SurfaceFrame title={title} eyebrow="Trace assembly" icon={icon}><Card className="border-white/10 bg-[#0c101a]/85"><CardHeader className="flex-row items-center justify-between"><CardTitle className="font-display text-sm uppercase tracking-[.14em] text-white">Investigation timeline</CardTitle><Badge className="border-cyan-300/20 bg-cyan-300/10 text-cyan-200">status: {status ?? "awaiting trace"}</Badge></CardHeader><CardContent className="space-y-3">{(dashboardSurface.data?.audit ?? []).slice(0, 10).map((event, index) => <div key={event.id} className="flex gap-3 border-l border-cyan-300/40 pl-4"><div className="grid h-5 w-5 place-items-center border border-cyan-300/30 font-mono text-[10px] text-cyan-200">{index + 1}</div><div className="flex-1"><div className="text-xs uppercase tracking-wider text-slate-300">{event.eventType.replaceAll("_", " ")}</div><div className="mt-1 text-[10px] text-slate-500">actor #{event.actorId} · {formatDate(event.createdAt)}</div></div><div className="text-[10px] uppercase tracking-widest text-slate-500">{event.status}</div></div>)}{!(dashboardSurface.data?.audit ?? []).length && <div className="py-8 text-center text-sm text-slate-500">No trace events are available yet.</div>}</CardContent></Card><div className="grid gap-4 md:grid-cols-3">{["request context", "schema context", "execution evidence"].map(item => <Card key={item} className="border-white/10 bg-white/[.02]"><CardContent className="p-5"><div className="text-[10px] uppercase tracking-widest text-cyan-300">evidence card</div><div className="mt-3 text-sm font-semibold text-white">{item}</div><div className="mt-2 text-xs leading-5 text-slate-500">Populates from the corresponding lifecycle event after a connected query run; empty states are intentional until evidence exists.</div><Badge className="mt-4 border-pink-300/20 bg-pink-300/5 text-pink-200">awaiting evidence</Badge></CardContent></Card>)}</div></SurfaceFrame>;
}

function SurfaceFrame({ title, eyebrow, icon, children }: { title: string; eyebrow: string; icon: React.ReactNode; children: React.ReactNode }) { return <div className="space-y-6"><div><div className="mb-2 flex items-center gap-2 text-xs uppercase tracking-[.22em] text-pink-300"><span className="h-px w-8 bg-pink-300" /> {eyebrow}</div><div className="flex items-center gap-3"><div className="grid h-10 w-10 place-items-center border border-cyan-300/30 bg-cyan-300/5 text-cyan-200">{icon}</div><h2 className="font-display text-3xl font-bold text-white">{title}</h2></div><p className="mt-2 max-w-2xl text-sm leading-6 text-slate-500">A controlled workspace for evidence, status, and operator decisions. No placeholder metrics are presented as real system findings.</p></div>{children}</div>; }

function MetricPanel({ label, value, detail }: { label: string; value: string | number; detail: string }) { return <Card className="border-white/10 bg-[#0c101a]/85"><CardContent className="p-5"><div className="text-[10px] uppercase tracking-widest text-slate-500">{label}</div><div className="mt-3 font-display text-3xl font-bold text-white">{value}</div><div className="mt-2 text-xs leading-5 text-slate-500">{detail}</div></CardContent></Card>; }

function EmptySurface({ text }: { text: string }) { return <div className="grid min-h-[260px] place-items-center border border-dashed border-white/10 bg-white/[.015] p-8 text-center"><div><div className="mx-auto mb-4 grid h-12 w-12 place-items-center border border-pink-300/30 bg-pink-300/5 text-pink-300"><Terminal className="h-5 w-5" /></div><p className="mx-auto max-w-lg text-sm leading-6 text-slate-500">{text}</p><Badge className="mt-5 border-cyan-300/30 bg-cyan-300/10 text-cyan-200">awaiting evidence</Badge></div></div>; }

function AuditLedger({ events }: { events: any[] }) { const [filter, setFilter] = useState(""); const [selected, setSelected] = useState<any>(null); const filtered = events.filter(event => `${event.eventType} ${event.status} ${event.requestId ?? ""}`.toLowerCase().includes(filter.toLowerCase())); return <div className="space-y-6"><div><div className="mb-2 uppercase tracking-[.22em] text-pink-300 text-xs">Immutable event stream</div><h2 className="font-display text-3xl font-bold text-white">Audit ledger</h2><p className="mt-2 text-sm text-slate-500">Lifecycle events are append-only and scoped to your workspace.</p></div><Input value={filter} onChange={event => setFilter(event.target.value)} placeholder="Filter event type, status, or request…" className="max-w-md border-white/10 bg-white/[.04] text-white placeholder:text-slate-600" /><Card className="border-white/10 bg-[#0c101a]/85"><CardContent className="p-0">{filtered.length ? filtered.map((event, index) => <div key={event.id} className={`grid gap-3 p-5 md:grid-cols-[140px_1fr_auto] md:items-center ${index ? "border-t border-white/8" : ""}`}><div className="font-mono text-[11px] text-slate-500">{formatDate(event.createdAt)}</div><div><div className="text-sm font-semibold uppercase tracking-wider text-white">{event.eventType.replaceAll("_", " ")}</div><div className="mt-1 text-xs text-slate-500">actor #{event.actorId} {event.requestId ? `· request #${event.requestId}` : ""}</div></div><div className="flex items-center gap-2"><Badge className={statusTone(event.status)}>{event.status}</Badge><Button size="sm" variant="ghost" onClick={() => setSelected(event)} className="text-cyan-200">Detail</Button></div></div>) : <div className="py-20 text-center text-sm text-slate-500">No audit events match this filter.</div>}</CardContent></Card>{selected && <Card className="border-cyan-300/20 bg-cyan-300/[.03]"><CardHeader className="flex-row items-center justify-between"><CardTitle className="font-display text-sm uppercase tracking-[.14em] text-white">Event detail / lifecycle trace</CardTitle><Button size="sm" variant="ghost" onClick={() => setSelected(null)} className="text-slate-400">Close</Button></CardHeader><CardContent><div className="mb-5 space-y-2">{events.filter(event => selected.requestId && event.requestId === selected.requestId).map((event, index) => <div key={event.id} className="flex items-center gap-3 border-l border-cyan-300/50 pl-3"><span className="font-mono text-[10px] text-slate-500">{index + 1}</span><span className="text-xs uppercase tracking-wider text-white">{event.eventType.replaceAll("_", " ")}</span><Badge className={statusTone(event.status)}>{event.status}</Badge></div>)}</div><pre className="overflow-auto whitespace-pre-wrap font-mono text-xs leading-6 text-cyan-50">{JSON.stringify(selected, null, 2)}</pre></CardContent></Card>}</div>; }

function ConnectDialog({ onClose, onSubmit, busy }: { onClose: () => void; onSubmit: (input: any) => void; busy: boolean }) { const [form, setForm] = useState({ displayName: "", host: "", port: 5432, databaseName: "", username: "", password: "", sslMode: "require" as const }); const update = (key: string, value: string | number) => setForm(current => ({ ...current, [key]: value })); return <div className="fixed inset-0 z-50 grid place-items-center bg-black/70 p-4 backdrop-blur-sm"><Card className="w-full max-w-2xl border-cyan-300/20 bg-[#0b101b] shadow-[0_0_80px_rgba(82,244,255,.12)]"><CardHeader className="flex-row items-start justify-between"><div><div className="mb-2 text-[10px] font-bold uppercase tracking-[.25em] text-cyan-300">Secure credential vault</div><CardTitle className="font-display text-xl text-white">Register PostgreSQL endpoint</CardTitle><p className="mt-2 text-xs leading-5 text-slate-500">Credentials are encrypted server-side and never sent to the browser after submission.</p></div><Button size="icon" variant="ghost" onClick={onClose} className="text-slate-500"><X className="h-4 w-4" /></Button></CardHeader><CardContent><div className="grid gap-4 sm:grid-cols-2">{[["displayName", "Display name", "Orders production"], ["host", "Host", "db.internal"], ["databaseName", "Database", "orders"], ["username", "Read-only username", "dbops_reader"], ["password", "Password", "••••••••"]].map(([key, label, placeholder]) => <div key={key} className={key === "displayName" ? "sm:col-span-2" : ""}><label className="mb-2 block text-[10px] font-bold uppercase tracking-widest text-slate-500">{label}</label><Input type={key === "password" ? "password" : "text"} value={(form as any)[key]} onChange={event => update(key, event.target.value)} placeholder={placeholder} className="border-white/10 bg-white/[.03] text-white placeholder:text-slate-700" /></div>)}<div><label className="mb-2 block text-[10px] font-bold uppercase tracking-widest text-slate-500">Port</label><Input type="number" value={form.port} onChange={event => update("port", Number(event.target.value))} className="border-white/10 bg-white/[.03] text-white" /></div><div><label className="mb-2 block text-[10px] font-bold uppercase tracking-widest text-slate-500">SSL mode</label><select value={form.sslMode} onChange={event => update("sslMode", event.target.value)} className="h-10 w-full border border-white/10 bg-[#080b13] px-3 text-sm text-white"><option value="require">require</option><option value="prefer">prefer</option><option value="disable">disable</option></select></div></div><Separator className="my-6 bg-white/10" /><div className="flex justify-end gap-3"><Button variant="ghost" onClick={onClose} className="text-slate-400">Cancel</Button><Button disabled={busy || !form.displayName || !form.host || !form.databaseName || !form.username || !form.password} onClick={() => onSubmit(form)} className="rounded-none bg-cyan-300 font-bold text-[#05070c] hover:bg-cyan-200"><KeyRound className="mr-2 h-4 w-4" /> {busy ? "Encrypting…" : "Save securely"}</Button></div></CardContent></Card></div>; }
